# ------------------------------------------------------------
# Helpers / database
# ------------------------------------------------------------
def uid(prefix):
    return prefix + "_" + uuid.uuid4().hex[:14]

def now_iso():
    return datetime.now().isoformat(timespec="seconds")

def esc(v):
    return html.escape("" if v is None else str(v))

def norm_email(v):
    return (v or "").strip().lower()

def pw_hash(p):
    return hashlib.sha256(("carelio::" + (p or "")).encode("utf-8")).hexdigest()

def db():
    con = sqlite3.connect(DB_PATH, check_same_thread=False)
    con.row_factory = sqlite3.Row
    return con

def run(sql, params=()):
    with db() as con:
        cur = con.execute(sql, params)
        con.commit()
        return cur.lastrowid

def rows(sql, params=()):
    with db() as con:
        return [dict(r) for r in con.execute(sql, params).fetchall()]

def row(sql, params=()):
    with db() as con:
        r = con.execute(sql, params).fetchone()
        return dict(r) if r else None

def ensure_column(table, column, sql_type):
    with db() as con:
        cols={r["name"] for r in con.execute("PRAGMA table_info("+table+")").fetchall()}
        if column not in cols:
            con.execute("ALTER TABLE "+table+" ADD COLUMN "+column+" "+sql_type)
            con.commit()

def ensure_schema():
    with db() as con:
        con.executescript("""
        CREATE TABLE IF NOT EXISTS community_users(
          id TEXT PRIMARY KEY,name TEXT,email TEXT UNIQUE,password_hash TEXT,phone TEXT,
          address TEXT,city TEXT,state TEXT,zip TEXT,language TEXT DEFAULT 'English',
          radius INTEGER DEFAULT 10,profile_b64 TEXT,active INTEGER DEFAULT 1,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS organizations(
          id TEXT PRIMARY KEY,name TEXT,official_email TEXT,website TEXT,phone TEXT,
          verification_status TEXT DEFAULT 'pending',is_test INTEGER DEFAULT 0,
          review_notes TEXT,verified_at TEXT,verified_by TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS org_staff(
          id TEXT PRIMARY KEY,org_id TEXT,name TEXT,email TEXT,phone TEXT,password_hash TEXT,
          role TEXT DEFAULT 'Staff',email_verified INTEGER DEFAULT 0,active INTEGER DEFAULT 1,
          created_at TEXT,last_login_at TEXT
        );
        CREATE TABLE IF NOT EXISTS otp_codes(
          id TEXT PRIMARY KEY,staff_id TEXT,code_hash TEXT,expires_at TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS locations(
          id TEXT PRIMARY KEY,org_id TEXT,name TEXT,address TEXT,city TEXT,county TEXT,state TEXT,zip TEXT,
          phone TEXT,hours TEXT,walk_in TEXT,appointment TEXT,id_required TEXT,eligibility TEXT,
          accessibility TEXT,active INTEGER DEFAULT 1,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS service_updates(
          id TEXT PRIMARY KEY,org_id TEXT,location_id TEXT,category TEXT,item TEXT,status TEXT,
          notes TEXT,updated_by TEXT,updated_at TEXT
        );
        CREATE TABLE IF NOT EXISTS org_events(
          id TEXT PRIMARY KEY,org_id TEXT,title TEXT,category TEXT,description TEXT,start_at TEXT,end_at TEXT,
          address TEXT,city TEXT,state TEXT,zip TEXT,active INTEGER DEFAULT 1,created_by TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS public_events(
          id TEXT PRIMARY KEY,title TEXT,category TEXT,description TEXT,start_at TEXT,end_at TEXT,
          location_name TEXT,address TEXT,city TEXT,state TEXT,zip TEXT,source_name TEXT,source_url TEXT,
          reviewed_at TEXT,active INTEGER DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS saved_events(
          id TEXT PRIMARY KEY,user_id TEXT,event_id TEXT,event_type TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS saved_locations(
          id TEXT PRIMARY KEY,user_id TEXT,location_id TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS requests(
          id TEXT PRIMARY KEY,org_id TEXT,user_id TEXT,location_id TEXT,request_type TEXT,details TEXT,
          status TEXT DEFAULT 'New',created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS appointment_slots(
          id TEXT PRIMARY KEY,org_id TEXT,location_id TEXT,title TEXT,start_at TEXT,
          capacity INTEGER DEFAULT 1,active INTEGER DEFAULT 1,created_by TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS appointments(
          id TEXT PRIMARY KEY,slot_id TEXT,org_id TEXT,user_id TEXT,status TEXT DEFAULT 'Booked',created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS searches(
          id TEXT PRIMARY KEY,user_id TEXT,category TEXT,needs_json TEXT,search_text TEXT,zip TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS audit_logs(
          id TEXT PRIMARY KEY,org_id TEXT,actor_id TEXT,actor_name TEXT,action TEXT,
          entity_type TEXT,entity_id TEXT,details TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS admins(
          id TEXT PRIMARY KEY,name TEXT,email TEXT UNIQUE,password_hash TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS admin_actions(
          id TEXT PRIMARY KEY,admin_id TEXT,action TEXT,target_type TEXT,target_id TEXT,reason TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS public_sources(
          id TEXT PRIMARY KEY,name TEXT,source_type TEXT,url TEXT,status TEXT DEFAULT 'active',
          last_checked_at TEXT,notes TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS event_sources(
          id TEXT PRIMARY KEY,name TEXT,source_type TEXT,url TEXT,status TEXT DEFAULT 'active',
          last_checked_at TEXT,notes TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS volunteers(
          id TEXT PRIMARY KEY,org_id TEXT,user_id TEXT,name TEXT,email TEXT,phone TEXT,
          active INTEGER DEFAULT 1,approved_by TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS volunteer_applications(
          id TEXT PRIMARY KEY,user_id TEXT,org_id TEXT,name TEXT,email TEXT,phone TEXT,
          service_zips TEXT,availability_note TEXT,status TEXT DEFAULT 'Pending',
          reviewed_by TEXT,reviewed_at TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS assistance_settings(
          org_id TEXT PRIMARY KEY,enabled INTEGER DEFAULT 0,
          assistance_types_json TEXT,service_zips TEXT,service_days TEXT,
          capacity_note TEXT,updated_at TEXT
        );
        CREATE TABLE IF NOT EXISTS assistance_requests(
          id TEXT PRIMARY KEY,user_id TEXT,org_id TEXT,location_id TEXT,
          category TEXT,items_json TEXT,reason_code TEXT,reason_details TEXT,
          assistance_type TEXT,delivery_address TEXT,delivery_notes TEXT,
          status TEXT DEFAULT 'Submitted',volunteer_id TEXT,
          created_at TEXT,updated_at TEXT
        );
        CREATE TABLE IF NOT EXISTS assistance_status_history(
          id TEXT PRIMARY KEY,request_id TEXT,status TEXT,note TEXT,
          actor_type TEXT,actor_id TEXT,created_at TEXT
        );
        CREATE TABLE IF NOT EXISTS notifications(
          id TEXT PRIMARY KEY,user_id TEXT,title TEXT,message TEXT,
          request_id TEXT,is_read INTEGER DEFAULT 0,created_at TEXT
        );
        """)
        # Safe migrations for service-level access rules.
        existing_cols={r[1] for r in con.execute("PRAGMA table_info(service_updates)").fetchall()}
        for coldef in [
            "service_hours TEXT",
            "walk_in TEXT",
            "appointment TEXT",
            "id_required TEXT",
            "eligibility TEXT"
        ]:
            colname=coldef.split()[0]
            if colname not in existing_cols:
                con.execute("ALTER TABLE service_updates ADD COLUMN "+coldef)

        volunteer_cols={r[1] for r in con.execute("PRAGMA table_info(volunteers)").fetchall()}
        if "user_id" not in volunteer_cols:
            con.execute("ALTER TABLE volunteers ADD COLUMN user_id TEXT")
        con.commit()

ensure_schema()

def audit(org_id, actor, action, entity_type="", entity_id="", details=""):
    run("""INSERT INTO audit_logs(id,org_id,actor_id,actor_name,action,entity_type,entity_id,details,created_at)
           VALUES(?,?,?,?,?,?,?,?,?)""",
        (uid("audit"),org_id,actor.get("id",""),actor.get("name",""),action,entity_type,entity_id,details,now_iso()))

def admin_action(admin, action, target_type, target_id, reason=""):
    run("INSERT INTO admin_actions(id,admin_id,action,target_type,target_id,reason,created_at) VALUES(?,?,?,?,?,?,?)",
        (uid("aa"),admin["id"],action,target_type,target_id,reason,now_iso()))


def notify_user(user_id,title,message,request_id=""):
    run("""INSERT INTO notifications(id,user_id,title,message,request_id,is_read,created_at)
           VALUES(?,?,?,?,?,0,?)""",
        (uid("note"),user_id,title,message,request_id,now_iso()))

def assistance_history(request_id,status,note="",actor_type="",actor_id=""):
    run("""INSERT INTO assistance_status_history(id,request_id,status,note,actor_type,actor_id,created_at)
           VALUES(?,?,?,?,?,?,?)""",
        (uid("hist"),request_id,status,note,actor_type,actor_id,now_iso()))

def assistance_status_message(status, volunteer_name=""):
    if status=="Submitted":
        return "Your assisted-access request was submitted."
    if status=="Organization Reviewing":
        return "The organization is reviewing your assisted-access request."
    if status=="Approved":
        return "Your assisted-access request was approved."
    if status=="Volunteer Assigned":
        return (volunteer_name+" was assigned to your request." if volunteer_name else "A verified volunteer was assigned to your request.")
    if status=="Volunteer Accepted":
        return (volunteer_name+" accepted your delivery." if volunteer_name else "A verified volunteer accepted your delivery.")
    if status=="Heading to Pickup":
        return (volunteer_name+" is heading to the pickup location." if volunteer_name else "Your volunteer is heading to the pickup location.")
    if status=="Picked Up":
        return "Your support items have been picked up."
    if status=="On the Way":
        return (volunteer_name+" is on the way to you." if volunteer_name else "Your delivery is on the way.")
    if status=="Delivered":
        return "Your assisted delivery has been marked delivered."
    if status=="Completed":
        return "Your assisted-access request is complete."
    if status=="Unable to Fulfill":
        return "The organization could not fulfill this request. Please check My Support for details."
    return "Your assisted-access request status was updated to "+status+"."

# ------------------------------------------------------------
# Embedded images
# ------------------------------------------------------------
@st.cache_data(show_spinner=False)
def pil_from_b64(data):
    return Image.open(io.BytesIO(base64.b64decode(data))).convert("RGB")

def photo_for_category(category):
    return pil_from_b64(ASSETS["category"][category])

def food_group_for_item(item):
    for g, vals in FOOD_GROUPS.items():
        if item in vals:
            return g
    return "Dairy"

def photo_for_item(category, item):
    key=re.sub(r"[^a-z0-9]+","_",item.lower()).strip("_")
    bucket="food_exact" if category=="Food" else "support"
    if key in ASSETS.get(bucket,{}):
        return pil_from_b64(ASSETS[bucket][key])
    if category=="Food":
        return pil_from_b64(ASSETS["food_exact"]["prepared_meal"])
    return pil_from_b64(ASSETS["support"]["family_support"])


def img_data_uri(b64):
    return "data:image/jpeg;base64," + b64

