def tr(text_value):
    code=st.session_state.get("language","en")
    return I18N.get(code,{}).get(text_value,I18N.get("en",{}).get(text_value,text_value))

def language_selector(key):
    labels=list(LANGUAGES.keys())
    codes=list(LANGUAGES.values())
    current=st.session_state.get("language","en")
    idx=codes.index(current) if current in codes else 0
    choice=st.selectbox("🌐 Language",labels,index=idx,key=key)
    st.session_state.language=LANGUAGES[choice]

