# Organization workspace
# ------------------------------------------------------------
ROLE={"Viewer":0,"Staff":1,"Manager":2,"Admin":3,"Owner":4}
def can(role):
    return ROLE.get(st.session_state.staff.get("role","Viewer"),0)>=ROLE[role]

def org_nav():
    st.markdown(LOGO_HTML,unsafe_allow_html=True)
    items=[("Dashboard","org_dashboard"),("Pantry & Access","org_locations"),("Forms + Requests","org_requests"),
           ("Appointments","org_appointments"),("Support Events","org_events"),
           ("Staff & Activity","org_staff"),("Insights","org_insights"),("Profile","org_profile")]
    cols=st.columns(len(items)+1)
    for i,(lab,p) in enumerate(items):
        with cols[i]:
            if st.button(tr(lab),key="orgnav_"+p):
                goto(p)
    with cols[-1]:
        if st.button(tr("Sign out"),key="orgout"):
            logout()
    o=st.session_state.org
    if o.get("is_test"):
        st.warning("TEST ORGANIZATION — excluded from Community/public results.")
    elif o.get("verification_status")=="pending":
        st.warning("PENDING Carelio verification. You can configure the workspace, but LIVE public publishing waits for Admin approval.")
    elif o.get("verification_status")=="verified":
        st.success("Verified Carelio Partner")

def render_org_dashboard():
    org_nav(); o=st.session_state.org
    st.markdown("<div class='page-title'>Organization Dashboard</div>",unsafe_allow_html=True)
    st.info("One organization = one shared workspace. Authorized staff see the same locations, services, events, requests and activity.")
    st.markdown(
        "<div class='result-card'><div class='result-title'>Pantry & Access Updates</div>"
        "<div class='result-meta'>Open <b>Pantry & Access</b> to update pantry/service lists, "
        "Available / Low / Out status, hours, walk-in rules, appointment requirements, ID requirements and eligibility. "
        "Verified updates flow directly to Community search results.</div></div>",
        unsafe_allow_html=True
    )
    if st.button("Update Pantry & Access",type="primary",key="org_dashboard_pantr_access"):
        goto("org_locations")

    vals=[
      ("Locations",len(rows("SELECT id FROM locations WHERE org_id=? AND active=1",(o["id"],)))),
      ("Service updates",len(rows("SELECT id FROM service_updates WHERE org_id=?",(o["id"],)))),
      ("Requests",len(rows("SELECT id FROM requests WHERE org_id=?",(o["id"],)))),
      ("Events",len(rows("SELECT id FROM org_events WHERE org_id=? AND active=1",(o["id"],))))
    ]
    cols=st.columns(len(vals))
    for i,(lab,v) in enumerate(vals):
        with cols[i]: st.metric(lab,v)

def render_org_locations():
    org_nav()
    o=st.session_state.org
    s=st.session_state.staff

    st.markdown("<div class='page-title'>Pantry & Access</div>",unsafe_allow_html=True)
    st.markdown(
        "<div class='page-sub'>Manage each location, pantry/service list, live availability and access requirements. "
        "These verified updates are what Community users see in Carelio.</div>",
        unsafe_allow_html=True
    )

    # --------------------------------------------------------
    # Add a new location
    # --------------------------------------------------------
    if can("Manager"):
        with st.expander("Add Location"):
            c1,c2=st.columns(2)
            with c1:
                name=st.text_input("Location name",key="oln")
                address=st.text_input("Address",key="ola")
                city=st.text_input("City",key="olc")
                county=st.text_input("County",key="olcounty")
                state=st.text_input("State",value="MN",key="ols")
                zipc=st.text_input("ZIP",key="olz")
            with c2:
                phone=st.text_input("Phone",key="olp")
                hours=st.text_input("Default location hours",key="olh")
                walk=st.selectbox("Default walk-in policy",
                                  ["Walk-in welcome","Walk-in limited","Call before visiting","Not available","Not published"],
                                  key="olw")
                appt=st.selectbox("Default appointment policy",
                                  ["Not required","Available","Required","Service-specific","Not published"],
                                  key="olap")
                idr=st.selectbox("Default ID requirement",
                                 ["No ID required","ID required","Service-specific","Call to confirm","Not published"],
                                 key="olid")
                elig=st.text_input("Default eligibility",key="ole")
                acc=st.text_input("Accessibility",key="olacc")
            if st.button("Add Location",type="primary",key="add_org_location"):
                lid=uid("loc")
                run("""INSERT INTO locations(id,org_id,name,address,city,county,state,zip,phone,hours,walk_in,appointment,id_required,eligibility,accessibility,active,created_at)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)""",
                    (lid,o["id"],name,address,city,county,state,zipc,phone,hours,walk,appt,idr,elig,acc,now_iso()))
                audit(o["id"],s,"Added location","location",lid,name)
                st.success("Location added.")
                st.rerun()

    locs=rows("SELECT * FROM locations WHERE org_id=? AND active=1 ORDER BY name",(o["id"],))
    if not locs:
        st.info("Add your first location to start publishing services.")
        return

    loc=st.selectbox("Choose location",locs,format_func=lambda x:x["name"],key="org_loc_select")

    tab_access,tab_services,tab_current=st.tabs(
        ["Location Access Settings","Pantry / Service Availability","Published Updates"]
    )

    # --------------------------------------------------------
    # Location-wide defaults
    # --------------------------------------------------------
    with tab_access:
        st.markdown("<div class='section-title'>Location access information</div>",unsafe_allow_html=True)
        st.caption("These are defaults. You can override them for a specific pantry item or service below.")

        c1,c2=st.columns(2)
        with c1:
            ed_hours=st.text_input("Hours",value=loc.get("hours") or "",key="ed_hours_"+loc["id"])
            ed_walk=st.selectbox(
                "Walk-in",
                ["Walk-in welcome","Walk-in limited","Call before visiting","Not available","Not published"],
                index=(["Walk-in welcome","Walk-in limited","Call before visiting","Not available","Not published"].index(loc.get("walk_in"))
                       if loc.get("walk_in") in ["Walk-in welcome","Walk-in limited","Call before visiting","Not available","Not published"] else 4),
                key="ed_walk_"+loc["id"]
            )
            ed_appt=st.selectbox(
                "Appointment",
                ["Not required","Available","Required","Service-specific","Not published"],
                index=(["Not required","Available","Required","Service-specific","Not published"].index(loc.get("appointment"))
                       if loc.get("appointment") in ["Not required","Available","Required","Service-specific","Not published"] else 4),
                key="ed_appt_"+loc["id"]
            )
        with c2:
            ed_id=st.selectbox(
                "ID requirement",
                ["No ID required","ID required","Service-specific","Call to confirm","Not published"],
                index=(["No ID required","ID required","Service-specific","Call to confirm","Not published"].index(loc.get("id_required"))
                       if loc.get("id_required") in ["No ID required","ID required","Service-specific","Call to confirm","Not published"] else 4),
                key="ed_id_"+loc["id"]
            )
            ed_elig=st.text_input("Eligibility",value=loc.get("eligibility") or "",key="ed_elig_"+loc["id"])
            ed_acc=st.text_input("Accessibility",value=loc.get("accessibility") or "",key="ed_acc_"+loc["id"])

        if can("Manager") and st.button("Save Location Access Settings",type="primary",key="save_loc_access_"+loc["id"]):
            run("""UPDATE locations
                   SET hours=?,walk_in=?,appointment=?,id_required=?,eligibility=?,accessibility=?
                   WHERE id=? AND org_id=?""",
                (ed_hours,ed_walk,ed_appt,ed_id,ed_elig,ed_acc,loc["id"],o["id"]))
            audit(o["id"],s,"Updated location access settings","location",loc["id"],loc["name"])
            st.success("Location access settings saved.")
            st.rerun()

    # --------------------------------------------------------
    # Pantry / services inventory
    # --------------------------------------------------------
    with tab_services:
        st.markdown("<div class='section-title'>Publish pantry or service availability</div>",unsafe_allow_html=True)
        st.markdown(
            "<div class='section-sub'>Select one or many items, then publish their availability. "
            "Use the service-specific access fields only when that item has different rules from the location defaults.</div>",
            unsafe_allow_html=True
        )

        category=st.selectbox(
            "Category",
            ["Food","Health","Baby & Family","Clothing","Hygiene","Community Services"],
            key="org_service_category"
        )

        if category=="Food":
            group=st.selectbox("Food group",list(FOOD_GROUPS),key="org_food_group")
            choices=FOOD_GROUPS[group]
            selected_items=st.multiselect(
                "Pantry items to update",
                choices,
                key="org_food_items"
            )
        else:
            selected_items=st.multiselect(
                "Services / items to update",
                SUPPORT_ITEMS[category],
                key="org_support_items_"+category
            )

        if selected_items:
            st.caption("Selected: "+", ".join(selected_items))

        c1,c2=st.columns(2)
        with c1:
            status=st.selectbox("Availability",["Available","Low","Out"],key="org_bulk_status")
            service_hours=st.text_input(
                "Service/item hours (optional)",
                placeholder="Leave blank to use location hours",
                key="org_service_hours"
            )
            walk_override=st.selectbox(
                "Walk-in for these items",
                ["Use location default","Walk-in welcome","Walk-in limited","Call before visiting","Not available","Not published"],
                key="org_walk_override"
            )
        with c2:
            appt_override=st.selectbox(
                "Appointment for these items",
                ["Use location default","Not required","Available","Required","Service-specific","Not published"],
                key="org_appt_override"
            )
            id_override=st.selectbox(
                "ID requirement for these items",
                ["Use location default","No ID required","ID required","Service-specific","Call to confirm","Not published"],
                key="org_id_override"
            )
            eligibility_override=st.text_input(
                "Eligibility for these items (optional)",
                placeholder="Leave blank to use location eligibility",
                key="org_elig_override"
            )

        notes=st.text_area(
            "Availability note",
            placeholder="Example: Eggs limited to one carton per household while supplies last.",
            key="org_update_note"
        )

        if can("Staff") and st.button("Publish Selected Items",type="primary",key="publish_selected_services"):
            if not selected_items:
                st.warning("Select at least one pantry item or service.")
            else:
                published=0
                walk_val="" if walk_override=="Use location default" else walk_override
                appt_val="" if appt_override=="Use location default" else appt_override
                id_val="" if id_override=="Use location default" else id_override

                for item in selected_items:
                    existing=row("SELECT * FROM service_updates WHERE location_id=? AND item=?",(loc["id"],item))
                    if existing:
                        run("""UPDATE service_updates
                               SET category=?,status=?,notes=?,updated_by=?,updated_at=?,
                                   service_hours=?,walk_in=?,appointment=?,id_required=?,eligibility=?
                               WHERE id=?""",
                            (category,status,notes,s["id"],now_iso(),
                             service_hours,walk_val,appt_val,id_val,eligibility_override,
                             existing["id"]))
                        sid=existing["id"]
                    else:
                        sid=uid("svc")
                        run("""INSERT INTO service_updates(
                                 id,org_id,location_id,category,item,status,notes,updated_by,updated_at,
                                 service_hours,walk_in,appointment,id_required,eligibility
                               ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                            (sid,o["id"],loc["id"],category,item,status,notes,s["id"],now_iso(),
                             service_hours,walk_val,appt_val,id_val,eligibility_override))
                    audit(o["id"],s,item+" → "+status,"service_update",sid,notes)
                    published+=1

                st.success(str(published)+" item(s) published to Carelio.")
                st.rerun()

        # Single-item detailed editor for existing items.
        existing_updates=rows(
            "SELECT * FROM service_updates WHERE location_id=? ORDER BY category,item",
            (loc["id"],)
        )
        if existing_updates:
            st.markdown("<div class='section-title'>Edit one published item</div>",unsafe_allow_html=True)
            edit=st.selectbox(
                "Published item",
                existing_updates,
                format_func=lambda x:(x.get("category","")+" · "+x.get("item","")+" · "+x.get("status","")),
                key="org_edit_service"
            )
            ec1,ec2=st.columns(2)
            with ec1:
                e_status=st.selectbox(
                    "Item availability",
                    ["Available","Low","Out"],
                    index=["Available","Low","Out"].index(edit.get("status")) if edit.get("status") in ["Available","Low","Out"] else 0,
                    key="e_status_"+edit["id"]
                )
                e_hours=st.text_input("Item/service hours",value=edit.get("service_hours") or "",key="e_hours_"+edit["id"])
                e_walk=st.text_input("Walk-in override",value=edit.get("walk_in") or "",key="e_walk_"+edit["id"])
            with ec2:
                e_appt=st.text_input("Appointment override",value=edit.get("appointment") or "",key="e_appt_"+edit["id"])
                e_id=st.text_input("ID override",value=edit.get("id_required") or "",key="e_id_"+edit["id"])
                e_elig=st.text_input("Eligibility override",value=edit.get("eligibility") or "",key="e_elig_"+edit["id"])
            e_notes=st.text_area("Item note",value=edit.get("notes") or "",key="e_notes_"+edit["id"])

            if can("Staff") and st.button("Save Item Update",key="save_item_"+edit["id"]):
                run("""UPDATE service_updates
                       SET status=?,service_hours=?,walk_in=?,appointment=?,id_required=?,eligibility=?,
                           notes=?,updated_by=?,updated_at=?
                       WHERE id=? AND org_id=?""",
                    (e_status,e_hours,e_walk,e_appt,e_id,e_elig,e_notes,s["id"],now_iso(),edit["id"],o["id"]))
                audit(o["id"],s,edit["item"]+" updated","service_update",edit["id"],e_notes)
                st.success("Item update saved.")
                st.rerun()

    # --------------------------------------------------------
    # Published updates table
    # --------------------------------------------------------
    with tab_current:
        ups=rows("""SELECT u.*,l.name location_name,st.name updated_by_name
                    FROM service_updates u
                    LEFT JOIN locations l ON l.id=u.location_id
                    LEFT JOIN org_staff st ON st.id=u.updated_by
                    WHERE u.org_id=? AND u.location_id=?
                    ORDER BY u.category,u.item""",(o["id"],loc["id"]))
        if ups:
            display=[]
            for u in ups:
                display.append({
                    "Location":u.get("location_name"),
                    "Category":u.get("category"),
                    "Item / Service":u.get("item"),
                    "Availability":u.get("status"),
                    "Service hours":u.get("service_hours") or loc.get("hours"),
                    "Walk-in":u.get("walk_in") or loc.get("walk_in"),
                    "Appointment":u.get("appointment") or loc.get("appointment"),
                    "ID required":u.get("id_required") or loc.get("id_required"),
                    "Eligibility":u.get("eligibility") or loc.get("eligibility"),
                    "Note":u.get("notes"),
                    "Updated by":u.get("updated_by_name"),
                    "Updated":u.get("updated_at")
                })
            st.dataframe(pd.DataFrame(display),hide_index=True)
        else:
            st.info("No service availability has been published for this location yet.")


