def _render_org_insights_engine():
    o=st.session_state.org

    # -----------------------------
    # 1. Observed Community demand
    # -----------------------------
    searches=rows("""
        SELECT s.user_id,s.category,s.needs_json,s.zip,s.created_at,
               u.zip user_zip
        FROM searches s
        LEFT JOIN community_users u ON u.id=s.user_id
        ORDER BY s.created_at DESC
    """)

    zip_to_county={"55105":"Ramsey","55106":"Ramsey","55108":"Ramsey"}
    for x in rows("SELECT zip,county FROM locations WHERE COALESCE(zip,'')<>'' AND COALESCE(county,'')<>''"):
        zip_to_county[str(x.get("zip","")).strip()]=str(x.get("county","")).strip()
    for rr in list(PUBLIC_RESOURCES)+list(PUBLIC_FOOD):
        if rr.get("zip") and rr.get("county"):
            zip_to_county[str(rr.get("zip")).strip()]=str(rr.get("county")).strip()

    category_demand={}
    item_demand={}
    county_demand={}
    zip_demand={}
    seen_cat=set()
    seen_item=set()
    unresolved=0

    for r in searches:
        category=(r.get("category") or "Unknown").strip()
        try:
            needs=json.loads(r.get("needs_json") or "[]")
            if not isinstance(needs,list):
                needs=[]
        except Exception:
            needs=[]
        if not needs:
            needs=[category]

        user=str(r.get("user_id") or "anonymous")
        day=str(r.get("created_at") or "")[:10]
        z=str(r.get("zip") or r.get("user_zip") or "").strip()
        county=zip_to_county.get(z,"")
        if z and not county:
            unresolved+=1

        cat_key=(user,day,category,z)
        if cat_key not in seen_cat:
            seen_cat.add(cat_key)
            category_demand[category]=category_demand.get(category,0)+1
            if county:
                county_demand.setdefault(county,{})
                county_demand[county][category]=county_demand[county].get(category,0)+1
            if z:
                zip_demand.setdefault(z,{})
                zip_demand[z][category]=zip_demand[z].get(category,0)+1

        for need in needs:
            need=str(need).strip()
            if not need:
                continue
            item_key=(user,day,need,z)
            if item_key in seen_item:
                continue
            seen_item.add(item_key)
            item_demand[need]=item_demand.get(need,0)+1

    # -----------------------------
    # 2. Verified Carelio supply
    # -----------------------------
    supply=rows("""
        SELECT u.item,u.category,u.status,u.location_id,u.updated_at,
               l.name location_name,l.city,l.county,l.zip,
               o.id org_id,o.name org_name
        FROM service_updates u
        JOIN locations l ON l.id=u.location_id
        JOIN organizations o ON o.id=u.org_id
        WHERE o.verification_status='verified'
          AND COALESCE(o.is_test,0)=0
          AND l.active=1
    """)

    county_supply={}
    zip_supply={}
    for r in supply:
        county=(r.get("county") or "").strip()
        z=(r.get("zip") or "").strip()
        cat=(r.get("category") or "Unknown").strip()
        if county:
            county_supply.setdefault(county,{}).setdefault(cat,set()).add(r.get("location_id"))
        if z:
            zip_supply.setdefault(z,{}).setdefault(cat,set()).add(r.get("location_id"))

    # Reviewed public/free/low-cost resource coverage
    public_count={}
    public_zip_count={}
    for r in list(PUBLIC_RESOURCES)+list(PUBLIC_FOOD):
        county=(r.get("county") or "").strip()
        z=(r.get("zip") or "").strip()
        cat=(r.get("category") or "Food").strip()
        if county:
            public_count.setdefault(county,{})
            public_count[county][cat]=public_count[county].get(cat,0)+1
        if z:
            public_zip_count.setdefault(z,{})
            public_zip_count[z][cat]=public_zip_count[z].get(cat,0)+1

    # -----------------------------
    # Header KPI cards
    # -----------------------------
    total_intents=sum(category_demand.values())
    active_need_count=len(item_demand)
    verified_locations=len(set(r.get("location_id") for r in supply if r.get("location_id")))
    counties_seen=len(county_demand)

    k1,k2,k3,k4=st.columns(4)
    with k1: st.metric("Observed Carelio demand",total_intents)
    with k2: st.metric("Specific needs searched",active_need_count)
    with k3: st.metric("Verified Carelio locations",verified_locations)
    with k4: st.metric("Counties with observed demand",counties_seen)

    st.markdown(
        "<div class='result-card'><div class='result-title'>How to read these insights</div>"
        "<div class='result-meta'>These numbers describe <b>observed activity inside Carelio</b>. "
        "They are not estimates of total county need. Demand comes from what Community users explicitly "
        "search/select before results are shown. Rapid repeat searches by the same user, need and day are de-duplicated.</div></div>",
        unsafe_allow_html=True
    )

    tabs=st.tabs(["Demand Overview","County & ZIP Expansion","Need vs Supply","Organization Coverage"])

    # -----------------------------
    # TAB 1 — Demand Overview
    # -----------------------------
    with tabs[0]:
        st.markdown("<div class='section-title'>What Community users are looking for</div>",unsafe_allow_html=True)

        if category_demand:
            total=max(sum(category_demand.values()),1)
            for cat,n in sorted(category_demand.items(),key=lambda x:x[1],reverse=True):
                pct=round((n/total)*100,1)
                st.markdown(
                    "<div class='result-card'><div class='result-title'>"+esc(cat)+
                    "</div><div class='result-meta'>Observed Carelio demand: <b>"+esc(n)+
                    "</b> · Share of observed demand: <b>"+esc(pct)+"%</b></div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("No Community search activity has been recorded yet. This section will populate as people use Carelio.")

        st.markdown("<div class='section-title'>Most requested specific needs</div>",unsafe_allow_html=True)
        if item_demand:
            for need,n in sorted(item_demand.items(),key=lambda x:x[1],reverse=True)[:20]:
                st.markdown(
                    "<div class='result-card'><div class='result-title'>"+esc(need)+
                    "</div><div class='result-meta'>Observed selections/searches: <b>"+esc(n)+"</b></div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("Specific item/service demand will appear after Community users select needs such as Milk, Rice, Diapers or Foot Care.")

    # -----------------------------
    # TAB 2 — County & ZIP Expansion
    # -----------------------------
    with tabs[1]:
        st.markdown("<div class='section-title'>Where should organizations investigate expansion?</div>",unsafe_allow_html=True)
        st.markdown(
            "<div class='result-card'><div class='result-meta'>Carelio compares observed search demand with "
            "<b>Verified Carelio supply</b> and <b>reviewed public/free or low-cost resources</b>. "
            "A strong signal means the area deserves investigation; it is not an automatic recommendation to open a site.</div></div>",
            unsafe_allow_html=True
        )

        if county_demand:
            for county,dby in sorted(county_demand.items(),key=lambda kv:sum(kv[1].values()),reverse=True):
                total=sum(dby.values())
                top_cat=max(dby,key=dby.get)
                top_n=dby[top_cat]
                verified=sum(len(v) for v in county_supply.get(county,{}).values())
                reviewed=sum(public_count.get(county,{}).values())

                if total>=10 and verified<=2:
                    signal="High expansion focus"
                elif total>=5 and verified<=2:
                    signal="Medium expansion focus"
                elif total>0 and verified==0:
                    signal="Investigate local gap"
                else:
                    signal="Monitor / strengthen coverage"

                st.markdown(
                    "<div class='result-card'><div class='result-title'>"+esc(county)+" County · "+esc(signal)+
                    "</div><div class='result-meta'>Observed Carelio demand: <b>"+esc(total)+
                    "</b><br>Leading category: <b>"+esc(top_cat)+"</b> ("+esc(top_n)+
                    ")<br>Verified Carelio locations: <b>"+esc(verified)+
                    "</b><br>Reviewed public/free or low-cost resources: <b>"+esc(reviewed)+
                    "</b><br><br><b>Planning question:</b> Is there enough accessible support where Carelio users are searching, "
                    "or should an organization consider a pop-up, mobile service, weekly distribution, partnership or additional service day?</div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("County-level expansion signals will appear after Community searches include ZIP information.")

        st.markdown("<div class='section-title'>ZIP-level opportunity</div>",unsafe_allow_html=True)
        if zip_demand:
            for z,dby in sorted(zip_demand.items(),key=lambda kv:sum(kv[1].values()),reverse=True):
                total=sum(dby.values())
                top=max(dby,key=dby.get)
                county=zip_to_county.get(z,"County not resolved")
                verified=sum(len(v) for v in zip_supply.get(z,{}).values())
                reviewed=sum(public_zip_count.get(z,{}).values())

                if total>=5 and verified==0:
                    signal="Strong local opportunity"
                elif total>=3 and verified<=1:
                    signal="Investigate local gap"
                else:
                    signal="Monitor"

                st.markdown(
                    "<div class='result-card'><div class='result-title'>ZIP "+esc(z)+" · "+esc(signal)+
                    "</div><div class='result-meta'>County: "+esc(county)+
                    "<br>Observed Carelio demand: <b>"+esc(total)+
                    "</b><br>Leading category: <b>"+esc(top)+
                    "</b><br>Verified Carelio locations in ZIP: <b>"+esc(verified)+
                    "</b><br>Reviewed resources in ZIP: <b>"+esc(reviewed)+"</b></div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("ZIP-level opportunity will populate as Carelio users search from specific ZIP codes.")

    # -----------------------------
    # TAB 3 — Need vs Supply
    # -----------------------------
    with tabs[2]:
        st.markdown("<div class='section-title'>Observed need compared with known supply</div>",unsafe_allow_html=True)

        gap_rows=[]
        for county,dby in county_demand.items():
            for cat,demand_n in dby.items():
                verified=len(county_supply.get(county,{}).get(cat,set()))
                reviewed=public_count.get(county,{}).get(cat,0)

                if demand_n>0 and verified==0 and reviewed==0:
                    signal="High gap · no known local supply"
                elif demand_n>=5 and verified<=1:
                    signal="Strengthen coverage"
                else:
                    signal="Demand present · monitor"

                gap_rows.append((demand_n,county,cat,verified,reviewed,signal))

        if gap_rows:
            for demand_n,county,cat,verified,reviewed,signal in sorted(gap_rows,reverse=True):
                st.markdown(
                    "<div class='result-card'><div class='result-title'>"+esc(county)+" · "+esc(cat)+
                    "</div><div class='result-meta'>Observed Carelio demand: <b>"+esc(demand_n)+
                    "</b><br>Verified Carelio locations: <b>"+esc(verified)+
                    "</b><br>Reviewed public/free or low-cost resources: <b>"+esc(reviewed)+
                    "</b><br>Signal: <b>"+esc(signal)+"</b></div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("Need-vs-supply comparisons will populate from real Community activity.")

    # -----------------------------
    # TAB 4 — Organization Coverage
    # -----------------------------
    with tabs[3]:
        st.markdown("<div class='section-title'>Your organization's current Carelio coverage</div>",unsafe_allow_html=True)

        own_locations=rows("SELECT * FROM locations WHERE org_id=? AND active=1",(o["id"],))
        own_updates=rows("SELECT * FROM service_updates WHERE org_id=? ORDER BY updated_at DESC",(o["id"],))
        own_counties=sorted(set((r.get("county") or "").strip() for r in own_locations if (r.get("county") or "").strip()))

        c1,c2,c3,c4=st.columns(4)
        with c1: st.metric("Active locations",len(own_locations))
        with c2: st.metric("Counties covered",len(own_counties))
        with c3: st.metric("Available",sum(1 for r in own_updates if r.get("status")=="Available"))
        with c4: st.metric("Low / Out",sum(1 for r in own_updates if r.get("status") in ("Low","Out")))

        if own_updates:
            for r in own_updates[:30]:
                loc=next((x for x in own_locations if x.get("id")==r.get("location_id")),None) or {}
                st.markdown(
                    "<div class='result-card'><div class='result-title'>"+esc(r.get("item",""))+
                    " · "+esc(r.get("status",""))+"</div><div class='result-meta'>Category: "+esc(r.get("category",""))+
                    "<br>Location: "+esc(loc.get("name",""))+
                    (("<br>"+esc(loc.get("city",""))+", "+esc(loc.get("county",""))+" County") if loc else "")+
                    "<br>Updated: "+esc(r.get("updated_at",""))+"</div></div>",
                    unsafe_allow_html=True
                )
        else:
            st.info("Your organization has not published availability updates yet.")

    if unresolved:
        st.caption(str(unresolved)+" search record(s) could not be assigned to a county because the ZIP was not mapped. Carelio does not guess counties.")


def render_org_insights():
    if st.session_state.get("auth")!="organization":
        st.error("Organization session is not active. Please sign in again.")
        return
    if not st.session_state.get("org") or not st.session_state.get("staff"):
        st.error("Organization workspace data is unavailable. Please sign in again.")
        return

    org_nav()
    st.markdown("<div class='page-title'>Carelio Insights</div>",unsafe_allow_html=True)
    st.markdown(
        "<div class='page-sub'>Understand what Community users are actively searching for, compare observed need with known support, "
        "and identify counties or ZIP codes that may deserve expansion planning.</div>",
        unsafe_allow_html=True
    )

    try:
        _render_org_insights_engine()
    except Exception as ex:
        st.warning("Insights could not finish loading, but your organization is still connected to Carelio.")
        st.info("The rest of the organization workspace remains available. Expand Technical detail below to see the exact analytics error.")
        with st.expander("Technical detail"):
            st.code(type(ex).__name__+": "+str(ex))


def render_org_profile():
    org_nav()
    o=st.session_state.org
    s=st.session_state.staff
    st.markdown("<div class='page-title'>Organization Profile</div>",unsafe_allow_html=True)

    current_lang_name=next((name for name,code in LANGUAGES.items() if code==st.session_state.get("language","en")),"English")

    c1,c2=st.columns(2)
    with c1:
        name=st.text_input("Organization name",value=o.get("name",""))
        em=st.text_input("Official email",value=o.get("official_email",""))
        web=st.text_input("Website",value=o.get("website",""))
        ph=st.text_input("Phone",value=o.get("phone",""))
        if can("Admin") and st.button("Save Organization Profile",type="primary"):
            run(
                "UPDATE organizations SET name=?,official_email=?,website=?,phone=? WHERE id=?",
                (name,norm_email(em),web,ph,o["id"])
            )
            st.session_state.org=row("SELECT * FROM organizations WHERE id=?",(o["id"],))
            st.rerun()

    with c2:
        nm=st.text_input("Your name",value=s.get("name",""),key="myn")
        phone=st.text_input("Your phone",value=s.get("phone",""),key="myp")
        st.text_input("Work email",value=s.get("email",""),disabled=True)
        st.text_input("Role",value=s.get("role",""),disabled=True)

        language_names=list(LANGUAGES.keys())
        ui_lang=st.selectbox(
            "Preferred interface language",
            language_names,
            index=language_names.index(current_lang_name),
            key="org_profile_language"
        )

        if st.button("Save My Profile"):
            run("UPDATE org_staff SET name=?,phone=? WHERE id=?",(nm,phone,s["id"]))
            st.session_state.staff=row("SELECT * FROM org_staff WHERE id=?",(s["id"],))
            st.session_state.language=LANGUAGES.get(ui_lang,"en")
            st.rerun()


