# Owner Admin
# ------------------------------------------------------------
def admin_route():
    try: return st.query_params.get("carelio_admin")=="owner"
    except Exception:
        try: return st.experimental_get_query_params().get("carelio_admin",[""])[0]=="owner"
        except Exception: return False

def render_admin_login():
    st.markdown(LOGO_HTML,unsafe_allow_html=True)
    st.markdown("<div class='page-title'>Carelio Owner Admin</div>",unsafe_allow_html=True)
    if not row("SELECT id FROM admins LIMIT 1"):
        st.warning("First-time private Owner setup.")
        name=st.text_input("Owner name",key="adn"); email=st.text_input("Owner email",key="ade"); pwd=st.text_input("Create Admin password",type="password",key="adp")
        if st.button("Create Owner Admin",type="primary"):
            if len(pwd)<8 or not norm_email(email) or not name:
                st.error("Use name, email and at least 8 characters for the password.")
            else:
                run("INSERT INTO admins(id,name,email,password_hash,created_at) VALUES(?,?,?,?,?)",(uid("admin"),name,norm_email(email),pw_hash(pwd),now_iso()))
                st.success("Admin created. Sign in.")
    else:
        email=st.text_input("Admin email",key="alie"); pwd=st.text_input("Admin password",type="password",key="alip")
        if st.button("Admin Sign In",type="primary"):
            a=row("SELECT * FROM admins WHERE lower(email)=?",(norm_email(email),))
            if a and hmac.compare_digest(a["password_hash"],pw_hash(pwd)):
                st.session_state.admin=a; goto("admin_dashboard")
            st.error("Incorrect Admin credentials.")

def admin_nav():
    items=[("Dashboard","admin_dashboard"),("Pending Approvals","admin_pending"),("Organizations","admin_orgs"),
           ("Community Accounts","admin_community"),("TEST Organizations","admin_tests"),("Sources","admin_sources"),("Audit & Safety","admin_audit")]
    cols=st.columns(len(items)+1)
    for i,(lab,p) in enumerate(items):
        with cols[i]:
            if st.button(lab,key="adnav_"+p): goto(p)
    with cols[-1]:
        if st.button("Sign out",key="adout"): st.session_state.admin=None; goto("landing")

def render_admin():
    a=st.session_state.admin
    st.markdown(LOGO_HTML,unsafe_allow_html=True); admin_nav()
    p=st.session_state.page
    if p=="admin_dashboard":
        pending=rows("SELECT * FROM organizations WHERE is_test=0 AND verification_status='pending'")
        cols=st.columns(5)
        vals=[("Pending",len(pending)),("Verified",len(rows("SELECT id FROM organizations WHERE is_test=0 AND verification_status='verified'"))),
              ("Suspended",len(rows("SELECT id FROM organizations WHERE is_test=0 AND verification_status='suspended'"))),
              ("Community",len(rows("SELECT id FROM community_users WHERE active=1"))),
              ("TEST orgs",len(rows("SELECT id FROM organizations WHERE is_test=1")))]
        for i,(lab,v) in enumerate(vals):
            with cols[i]: st.metric(lab,v)
        if pending: st.warning(str(len(pending))+" organization request(s) need review.")
        st.markdown("<div class='section-title'>Carelio county demand vs verified supply</div>",unsafe_allow_html=True)
        sr=rows("SELECT needs_json,category FROM searches")
        vu=rows("""SELECT u.item,u.status,u.location_id FROM service_updates u
                   JOIN organizations o ON o.id=u.org_id
                   JOIN locations l ON l.id=u.location_id
                   WHERE o.verification_status='verified' AND COALESCE(o.is_test,0)=0 AND l.active=1""")
        dem={}
        for x in sr:
            try: needs=json.loads(x.get("needs_json") or "[]")
            except Exception: needs=[]
            if not needs: needs=[x.get("category") or "Unknown"]
            for n in needs: dem[n]=dem.get(n,0)+1
        sup={}
        for x in vu:
            it=x.get("item") or "Unknown"
            sup.setdefault(it,set()).add(x.get("location_id"))
        gaps=[{"Need":k,"Community demand":v,"Confirmed partner locations":len(sup.get(k,set()))}
              for k,v in dem.items()]
        gaps=sorted(gaps,key=lambda r:(-r["Community demand"],r["Confirmed partner locations"]))
        if gaps:
            st.dataframe(pd.DataFrame(gaps),hide_index=True)
        else:
            st.info("Demand-vs-supply analytics will populate from actual Community searches and verified partner updates.")

    elif p=="admin_pending":
        st.markdown("<div class='page-title'>Pending Organization Approvals</div>",unsafe_allow_html=True)
        for o in rows("SELECT * FROM organizations WHERE is_test=0 AND verification_status='pending' ORDER BY created_at"):
            owner=row("SELECT * FROM org_staff WHERE org_id=? AND role='Owner' LIMIT 1",(o["id"],))
            st.markdown("<div class='result-card'><div class='result-title'>"+esc(o["name"])+"</div><div class='result-meta'>"+esc(o.get("official_email",""))+"<br>"+esc(o.get("website",""))+"<br>Owner: "+esc(owner.get("name","") if owner else "")+" · "+esc(owner.get("email","") if owner else "")+"<br>Owner email verified: "+("Yes" if owner and owner.get("email_verified") else "No")+"</div></div>",unsafe_allow_html=True)
            reason=st.text_input("Review note",key="r_"+o["id"])
            c1,c2,c3=st.columns(3)
            with c1:
                if st.button("Approve",type="primary",key="ap_"+o["id"]):
                    if not owner or not owner.get("email_verified"): st.error("Owner work email must be verified.")
                    else:
                        run("UPDATE organizations SET verification_status='verified',review_notes=?,verified_at=?,verified_by=? WHERE id=?",(reason,now_iso(),a["id"],o["id"]))
                        admin_action(a,"Approved organization","organization",o["id"],reason); st.rerun()
            with c2:
                if st.button("Reject",key="re_"+o["id"]):
                    run("UPDATE organizations SET verification_status='rejected',review_notes=? WHERE id=?",(reason,o["id"])); admin_action(a,"Rejected organization","organization",o["id"],reason); st.rerun()
            with c3:
                if st.button("Suspend",key="su_"+o["id"]):
                    run("UPDATE organizations SET verification_status='suspended',review_notes=? WHERE id=?",(reason,o["id"])); admin_action(a,"Suspended organization","organization",o["id"],reason); st.rerun()
    elif p=="admin_orgs":
        orgs=rows("SELECT * FROM organizations WHERE is_test=0 ORDER BY created_at DESC")
        if orgs: st.dataframe(pd.DataFrame(orgs),hide_index=True)
    elif p=="admin_community":
        for u in rows("SELECT id,name,email,phone,active,created_at FROM community_users ORDER BY created_at DESC"):
            st.markdown("<div class='result-card'><div class='result-title'>"+esc(u["name"])+"</div><div class='result-meta'>"+esc(u["email"])+" · "+("Active" if u["active"] else "Suspended")+"</div></div>",unsafe_allow_html=True)
            if u["active"]:
                if st.button("Suspend",key="cs_"+u["id"]): run("UPDATE community_users SET active=0 WHERE id=?",(u["id"],)); admin_action(a,"Suspended community account","community",u["id"]); st.rerun()
            else:
                if st.button("Restore",key="cr_"+u["id"]): run("UPDATE community_users SET active=1 WHERE id=?",(u["id"],)); admin_action(a,"Restored community account","community",u["id"]); st.rerun()
    elif p=="admin_tests":
        st.markdown("<div class='page-title'>TEST Organizations</div>",unsafe_allow_html=True)
        with st.expander("Create TEST Organization",expanded=True):
            n=st.text_input("TEST organization name",value="Carelio TEST Organization",key="tn")
            e=st.text_input("TEST Owner login email",value="test-org@carelio.local",key="te")
            pw=st.text_input("TEST password",type="password",value="CarelioTest123!",key="tp")
            if st.button("Create TEST Organization",type="primary"):
                if row("SELECT id FROM org_staff WHERE lower(email)=?",(norm_email(e),)): st.error("That email already exists.")
                else:
                    oid=uid("torg"); sid=uid("tstaff")
                    run("INSERT INTO organizations(id,name,official_email,website,phone,verification_status,is_test,verified_at,verified_by,created_at) VALUES(?,?,?,?,?,'verified',1,?,?,?)",(oid,n,norm_email(e),"https://carelio.local/test","000-000-0000",now_iso(),a["id"],now_iso()))
                    run("INSERT INTO org_staff(id,org_id,name,email,phone,password_hash,role,email_verified,active,created_at) VALUES(?,?,?,?,?,?,'Owner',1,1,?)",(sid,oid,"Carelio Tester",norm_email(e),"",pw_hash(pw),now_iso()))
                    admin_action(a,"Created TEST organization","organization",oid,n); st.success("TEST organization created."); st.rerun()
        tests=rows("SELECT * FROM organizations WHERE is_test=1")
        if tests: st.dataframe(pd.DataFrame(tests),hide_index=True)
    elif p=="admin_sources":
        tabs=st.tabs(["Public Sources","Event Sources","Reviewed Public Events"])
        with tabs[0]:
            name=st.text_input("Public source name",key="psn"); typ=st.selectbox("Source type",["Official Website","Government","Nonprofit Directory","Public Program Page"],key="pst"); url=st.text_input("URL",key="psu")
            if st.button("Add Public Source"): run("INSERT INTO public_sources(id,name,source_type,url,status,last_checked_at,notes,created_at) VALUES(?,?,?,?,?,?,?,?)",(uid("ps"),name,typ,url,"active",now_iso(),"",now_iso())); st.rerun()
            ps=rows("SELECT * FROM public_sources ORDER BY created_at DESC")
            if ps: st.dataframe(pd.DataFrame(ps),hide_index=True)
        with tabs[1]:
            name=st.text_input("Event source name",key="esn"); typ=st.selectbox("Source type",["Official Events Page","Public Google Calendar","ICS Feed","Public Program Page"],key="est"); url=st.text_input("URL",key="esu")
            if st.button("Add Event Source"): run("INSERT INTO event_sources(id,name,source_type,url,status,last_checked_at,notes,created_at) VALUES(?,?,?,?,?,?,?,?)",(uid("es"),name,typ,url,"active",now_iso(),"",now_iso())); st.rerun()
            es=rows("SELECT * FROM event_sources ORDER BY created_at DESC")
            if es: st.dataframe(pd.DataFrame(es),hide_index=True)
        with tabs[2]:
            with st.expander("Add reviewed public support event"):
                title=st.text_input("Title",key="pet"); cat=st.selectbox("Category",["Food","Health","Foot Care","Baby & Family","Clothing","Hygiene"],key="pec")
                desc=st.text_area("Description",key="ped"); d=st.date_input("Date",value=date.today()+timedelta(days=1),key="peday"); tm=st.text_input("Start HH:MM",value="10:00",key="petm")
                loc=st.text_input("Location name",key="pel"); address=st.text_input("Address",key="pea"); city=st.text_input("City",key="pecity"); source=st.text_input("Source name",key="pes")
                if st.button("Publish Reviewed Public Event"):
                    run("INSERT INTO public_events(id,title,category,description,start_at,end_at,location_name,address,city,state,zip,source_name,source_url,reviewed_at,active) VALUES(?,?,?,?,?,?,?,?,?,'MN','',?,'',?,1)",
                        (uid("pe"),title,cat,desc,d.isoformat()+"T"+tm,d.isoformat()+"T"+tm,loc,address,city,source,now_iso())); st.rerun()
            pe=rows("SELECT * FROM public_events ORDER BY start_at")
            if pe: st.dataframe(pd.DataFrame(pe),hide_index=True)
    elif p=="admin_audit":
        aa=rows("""SELECT x.created_at,a.name admin_name,x.action,x.target_type,x.target_id,x.reason
                   FROM admin_actions x LEFT JOIN admins a ON a.id=x.admin_id ORDER BY x.created_at DESC LIMIT 300""")
        if aa: st.dataframe(pd.DataFrame(aa),hide_index=True)
        logs=rows("SELECT created_at,org_id,actor_name,action,entity_type,details FROM audit_logs ORDER BY created_at DESC LIMIT 300")
        if logs: st.dataframe(pd.DataFrame(logs),hide_index=True)

# ------------------------------------------------------------
# Router
# ------------------------------------------------------------
if admin_route():
    if not st.session_state.admin: render_admin_login()
    else: render_admin()
    st.stop()

p=st.session_state.page

if st.session_state.auth=="community":
    if p=="home": render_home()
    elif p=="support_hub": render_support_hub()
    elif p=="category": render_category()
    elif p=="events": render_events()
    elif p=="event_detail": render_event_detail()
    elif p=="location_detail": render_location_detail()
    elif p=="my_support": render_my_support()
    elif p=="profile": render_profile()
    else: goto("home")
elif st.session_state.auth=="organization":
    if p=="org_dashboard": render_org_dashboard()
    elif p=="org_locations": render_org_locations()
    elif p=="org_requests": render_org_requests()
    elif p=="org_appointments": render_org_appointments()
    elif p=="org_events": render_org_events()
    elif p=="org_staff": render_org_staff()
    elif p=="org_insights": render_org_insights()
    elif p=="org_profile": render_org_profile()
    else: goto("org_dashboard")
else:
    if p=="community_register": render_community_register()
    elif p=="org_register": render_org_register()
    elif p=="otp": render_otp()
    else: render_landing()
